import { Component } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { AsyncPipe, CommonModule } from '@angular/common';

@Component({
  selector: 'app-counter',
  standalone: true,
  imports: [CommonModule],
  template: `
    <p>Count: {{ count$ | async }} <!-- ❌ OLD: async pipe subscribes + marks dirty per emission --></p>
    <button (click)="increment()">+1</button>
  `
})
export class CounterComponent {
  count$ = new BehaviorSubject<number>(0); // ❌ OLD: Subject state lives outside change detection

  increment(): void {
    // Subject state lives outside change detection; the async pipe
    // subscribes and marks the component dirty on each emission.
    this.count$.next(this.count$.value + 1);
  }
}

import { Component, signal, computed } from '@angular/core';

@Component({
  selector: 'app-counter',
  template: `
    <p>Count: {{ count() }} <!-- ✅ NEW: count() registers the template as a consumer --></p>
    <p>Twice: {{ doubled() }}</p>
    <button (click)="increment()">+1</button>
  `
})
export class CounterComponent {
  count = signal(0); // ✅ NEW: signal() — pull-based, granular
  doubled = computed(() => this.count() * 2); // ✅ NEW: computed() memoizes lazily

  increment(): void {
    this.count.update((v) => v + 1);
  }
}
